import java.util.Scanner;

public class Prepare {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int num = sc.nextInt();
        String str = sc.next();
        int maxSeq = 0;
        int currentSeq = 0;
        int underscoreTotal = 0;
        boolean inParentheses = false;
        boolean lastCharLetter = false;

        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if ((c > 96 && c < 123) || (c > 64 && c < 91)) {
                if (inParentheses && !lastCharLetter)
                    underscoreTotal++;
                if (!inParentheses)
                    currentSeq++;
                if (currentSeq > maxSeq)
                    maxSeq = currentSeq;
                lastCharLetter = true;
            } else if (c == '_') {
                lastCharLetter = false;
                if (currentSeq > maxSeq)
                    maxSeq = currentSeq;
                currentSeq = 0;
            } else if (c == '(') {
                lastCharLetter = false;
                inParentheses = true;
                if (currentSeq > maxSeq)
                    maxSeq = currentSeq;
                currentSeq = 0;
            } else if (c == ')') {
                inParentheses = false;
                lastCharLetter = false;
                if (currentSeq > maxSeq)
                    maxSeq = currentSeq;
                currentSeq = 0;
            }
        }
        System.out.println(maxSeq + " " + underscoreTotal);
        sc.close();
    }
}
